def sort_even(l: list):
    even = l[::2]  # Extract elements at even indices
    even_sorted = sorted(even)
    new_list = []
    for i in range(len(l)):
        if i % 2 == 0:
            new_list.append(even_sorted[i // 2])
        else:
            new_list.append(l[i])
    return new_list

def prime_fib(n):
    def is_prime(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        w = 2
        while i * i <= num:
            if num % i == 0:
                return False
            i += w
            w = 6 - w
        return True

    a, b = 1, 1
    primes = []
    while len(primes) < n:
        next_fib = a + b
        if is_prime(next_fib):
            primes.append(next_fib)
        a, b = b, next_fib
    return primes[n-1]

def pairs_sum_to_zero(l):
