def eulerian_number(n, m):
    if m < 0 or m > n - 1:
        return 0
    if m == 0:
        return 1
    total = 0
    for k in range(m + 1):
        sign = (-1) ** k
        comb = math.comb(n + 1, k)
        term = sign * comb * (m + 1 - k) ** n
        total += term
    return total

