def sum_amicable(max_num):
    def sum_proper(n):
        if n == 0:
            return 0
        if n == 1:
            return 0
        sum_div = 1
        sqrt_n = int(math.sqrt(n))
        for i in range(2, sqrt_n + 1):
            if n % i == 0:
                sum_div += i
                other = n // i
                if other != i and other != n:
                    sum_div += other
        return sum_div

    amicable = set()
    for i in range(1, max_num + 1):
        sum_i = sum_proper(i)
        if sum_i > max_num:
            continue
        sum_j = sum_proper(sum_i)
        if sum_j == i and sum_i != i:
            amicable.add(i)
            amicable.add(sum_i)
    return sum(amicable)

