def is_magic_square(matrix):
    n = len(matrix)
    if n == 0:
        return False
    # Check if the matrix is square
    for row in matrix:
        if len(row) != n:
            return False
    # Calculate the target sum (sum of the first row)
    target = sum(matrix[0])
    # Check each row
    for row in matrix:
        if sum(row) != target:
            return False
    # Check each column
    for i in range(n):
        column_sum = 0
        for j in range(n):
            column_sum += matrix[j][i]
        if column_sum != target:
            return False
    # Check main diagonal
    for i in range(n):
        if sum(matrix[i][i]) != target:
            return False
    # Check other diagonal
    for i in range(n):
        if sum(matrix[i][n-1-i]) != target:
            return False
    # All checks passed
    return True

