def sort_even(l: list):
    even_indices = [l[i] for i in range(0, len(l), 2)]
    sorted_even = sorted(even_indices)
    new_list = []
    for i in range(len(l)):
        if i % 2 == 0:
            new_list.append(sorted_even[i // 2])
        else:
            new_list.append(l[i])
    return new_list

def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    w = 2
    while i * i <= num:
        if num % i == 0:
            return False
        i += w
        w = 6 - w
    return True

def prime_fib(n):
    primes = []
    a, b = 0, 1
    count = 0
    while len(primes) < n:
        next_num = a + b
        a, b = b, next_num
        if is_prime(next_num):
            primes.append(next_num)
            count += 1
    return primes[n-1]

def change_base(x: int, base: int):
    if x == 0:
        return '0'
    s = ''
    while x > 0:
        s += str(x % base)
        x = x // base
    return s[::-1]

def is_palindrome(text: str):
    if not text:
        return True
    return text == text[::-1]

def remove_vowels(text):
    result = ""
    for char in text:
        if char.lower() not in {'a', 'e', 'i', 'o', 'u'}:
            result += char
    return result

def below_threshold(l, t):
    if not l:
        return True
    for num in l:
        if num >= t:
            return False
    return True

def fib(n):
    if n == 1 or n == 2:
        return 1
    a, b = 1, 1
    for i in range(3, n + 1):
        c = a + b
        a = b
        b = c
    return b

def monotonic(l):
    if len(l) <= 1:
        return True
    a, b = l[0], l[1]
    if a == b:
        return True
    increasing = False
    decreasing = False
    if b > a:
        increasing = True
    elif b < a:
        decreasing = True
    for i in range(2, len(l)):
        current = l[i]
        prev = l[i-1]
        if increasing:
            if current < prev:
                return False
        elif decreasing:
            if current > prev:
                return False
    return True

def largest_prime_factor(n: int) -> int:
    # Handle the case where n is even
    largest_factor = 2
    while n % 2 == 0:
        n = n // 2
        if n == 1:
            break
        largest_factor = 2
    # Now n is odd, check for factors from 3 upwards
    i = 3
    while i * i <= n:
        while n % i == 0:
            largest_factor = n // i
            n = n // i
        i += 2
    # If remaining n is a prime
    if n > 1:
        largest_factor = n
    return largest_factor

def sum_to_n(n):
    if n < 1:
        return 0
    return n * (n + 1) // 2

def correct_bracketing(brackets: str):
    stack = []
    for char in brackets:
        if char == '(':
            stack.append(char)
        else:
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

def fibfib(n):
    if n == 0:
        return 0
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        a, b, c = 0, 0, 1
        for i in range(3, n + 1):
            next_val = a + b + c
            a, b, c = b, c, next_val
        return c

def vowels_count(s):
    count = 0
    s_lower = s.lower()
    for i, char in enumerate(s_lower):
        if char == 'y' and i == len(s_lower) - 1:
            count += 1
        elif char in {'a', 'e', 'i', 'o', 'u'}:
            count += 1
    return count

