    if n == 0:
        return 0
    # Create a DP table to store lengths of longest palindromic subsequences
    dp = [[0] * n for _ in range(n)]

    for i in range(n-1, -1, -1):
        for j in range(i, n):
            if i == j:
                dp[i][j] = 1
            elif arr[i] == arr[j]:
                dp[i][j] = 2 + dp[i+1][j-1]
            else:
                dp[i][j] = max(dp[i+1][j], dp[i][j-1])

    # The maximum length of the palindromic subsequence
    lps = max(dp[i][j] for i in range(n) for j in range(i, n))
    return n - lps

