        direction = 'increasing'
    elif current < prev:
        direction = 'decreasing'
    else:
        direction = 'equal'
    # Iterate through the array starting from the third element
    for i in range(2, len(arr)):
        prev = arr[i-1]
        current = arr[i]
        if direction == 'increasing':
            if current > prev:
                continue
            else:
                return False
        elif direction == 'decreasing':
            if current < prev:
                return False
            else:
                continue
        else:  # direction is 'equal'
