def sum_common_divisors(a, b):
    def gcd(x, y):
        while y != 0:
            x, y = y, x % y
        return x

    gcd_value = gcd(a, b)
    if gcd_value == 0:
        return 0

    sum_divisors = 0
    sqrt_gcd = int(math.sqrt(gcd_value))

    for i in range(1, sqrt_gcd + 1):
        if gcd_value % i == 0:
            sum_divisors += i
            if i != gcd_value // i:
                sum_divisors += gcd_value // i

    return sum_divisors

def is_magic_square(matrix):
    n = len(matrix)
    if n == 0:
        return False
    for row in matrix:
        if len(row) != n:
            return False
    magic_constant = sum(matrix[0])

    # Check all rows
    for row in matrix:
        if sum(row) != magic_constant:
            return False

    # Check all columns
    for i in range(n):
        column_sum = 0
        for j in range(n):
            column_sum += matrix[j][i]
        if column_sum != magic_constant:
            return False

    # Check main diagonal
    main_diagonal_sum = 0
    for i in range(n):
        main_diagonal_sum += matrix[i][i]
    if main_diagonal_sum != magic_constant:
        return False

    # Check anti-diagonal
    anti_diagonal_sum = 0
    for i in range(n):
        anti_diagonal_sum += matrix[i][n-1-i]
    if anti_diagonal_sum != magic_constant:
        return False

    return True

