def sum_common_divisors(x, y):
    a = abs(x)
    b = abs(y)

    if a == 0 and b == 0:
        return 0
    if a == 0 or b == 0:
        return 0

    g = math.gcd(a, b)
    if g == 0:
        return 0

    divisors = set()
    for i in range(1, int(math.sqrt(g)) + 1):
        if g % i == 0:
            divisors.add(i)
            divisors.add(g // i)

    return sum(divisors)

def is_magic_square(matrix):
    n = len(matrix)
    if n == 0:
        return False

    # Calculate the magic constant using the first row
    magic = sum(matrix[0])

    # Check all rows
    for row in matrix:
        if sum(row) != magic:
            return False

    # Check all columns
    for j in range(n):
        column_sum = 0
        for i in range(n):
            column_sum += matrix[i][j]
        if column_sum != magic:
            return False

    # Check main diagonal
    for i in range(n):
        current = 0
        for j in range(n):
            current += matrix[i][j]
        if current != magic:
            return False

    # Check other diagonal
    for i in range(n):
        current = 0
        for j in range(n):
            current += matrix[j][n - 1 - i]
        if current != magic:
            return False

    return True

