    return result

def reverse_vowels(s):
    vowels = []
    for char in s:
        if char.lower() in {'a', 'e', 'i', 'o', 'u'}:
            vowels.append(char)
    vowels = vowels[::-1]
    result = []
    for char in s:
        if char.lower() in {'a', 'e', 'i', 'o', 'u'}:
            result.append(vowels.pop())
        else:
            result.append(char)
    return ''.join(result)

