    if n == 0:
        return False
    target = (n + 1) // 2
    first = arr[0]
    last = arr[-1]

    # Count occurrences of the first element
    last_first_index = -1
    for i in range(n-1, -1, -1):
        if arr[i] == first:
            last_first_index = i
        else:
            break
    count_first = last_first_index + 1
    if count_first >= target:
        return True

    # Count occurrences of the last element
    first_last_index = 0
    for i in range(n):
        if arr[i] == last:
            first_last_index = i
        else:
            break
    count_last = first_last_index + 1
    if count_last >= target:
        return True

    return False

