def parse_nested_parens(paren_string: str) -> List[int]:
    groups = paren_string.split()
    result = []
    for group in groups:
        current_depth = 0
        max_depth = 0
        for char in group:
            if char == '(':
                current_depth += 1
            else:
                current_depth -= 1
            if current_depth > max_depth:
                max_depth = current_depth
        result.append(max_depth)
    return result

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    if not numbers:
        return (0, 1)
    sum_total = 0
    product_total = 1
    for num in numbers:
        sum_total += num
        product_total *= num
    return (sum_total, product_total)

def rolling_max(numbers: List[int]) -> List[int]:
    if not numbers:
        return []
    result = [numbers[0]]
    for num in numbers[1:]:
        if num > result[-1]:
            result.append(num)
        else:
            result.append(result[-1])
    return result

def longest(strings: List[str]) -> Optional[str]:
    if not strings:
        return None
    max_length = 0
    result = None
    for s in strings:
        current_length = len(s)
        if current_length > max_length:
            max_length = current_length
            result = s
    return result

def greatest_common_divisor(a, b):
    if a == 0 and b == 0:
        return 0
    a = abs(a)
    b = abs(b)
    while b != 0:
        a, b = b, a % b
    return a

def how_many_times(s, t):
    count = 0
    n = len(t)
    m = len(s)
    if n == 0:
        return 0
    for i in range(m - n + 1):
        if s[i:i+n] == t:
            count += 1
    return count

def rescale_to_unit(numbers: List[float]) -> List[float]:
    min_val = min(numbers)
    max_val = max(numbers)
    if min_val == max_val:
        return [0.0] * len(numbers)
    else:
        return [(x - min_val) / (max_val - min_val) for x in numbers]

