def largest_divisor(n):
    if n == 1:
        return 0
    spf = None
    if n % 2 == 0:
        spf = 2
    else:
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                spf = i
                break
        if spf is None:
            spf = n
    return n // spf

def filter_by_prefix(strings: List[str], prefix: str) -> List[str]:
