import math

def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    max_divisor = math.sqrt(n)
    for i in range(3, int(max_divisor) + 1, 2):
        if n % i == 0:
            return False
    return True

def sort_third(l):
    # Collect indices that are divisible by 3
    indices = [i for i in range(len(l)) if i % 3 == 0]
    # Extract and sort the values at these indices
    sorted_values = sorted(l[i] for i in indices)
    # Create the result list
    result = []
    for i in range(len(l)):
        if i % 3 == 0:
            result.append(sorted_values.pop(0))
        else:
            result.append(l[i])
    return result

def fizz_buzz(n):
    count = 0
    for num in range(1, n):
        if num % 11 == 0 or num % 13 == 0:
            count += str(num).count('7')
    return count

def sort_even(l: list):
    # Extract elements at even indices
    evens = [l[i] for i in range(len(l)) if i % 2 == 0]
    # Sort the extracted elements
    evens_sorted = sorted(evens)
    # Reconstruct the new list
    new_list = []
    for i in range(len(l)):
        if i % 2 == 0:
            new_list.append(evens_sorted[i // 2])
        else:
            new_list.append(l[i])
    return new_list

def prime_fib(n):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    a, b = 1, 1
    next_num = 2
    primes = []
    while len(primes) < n:
        if is_prime(next_num):
            primes.append(next_num)
        a, b = b, next_num
        next_num = a + b
    return primes[-1]

def fib4(n):
    if n == 0:
        return 0
    elif n == 1:
        return 0
    elif n == 2:
        return 2
    elif n == 3:
        return 0
    else:
        a, b, c, d = 0, 0, 2, 0
        for i in range(4, n + 1):
            next_val = a + b + c + d
            a, b, c, d = b, c, d, next_val
        return d

def median(l: list):
