        a = b
        b = c
    return b

def monotonic(l):
    if len(l) <= 1:
        return True
    # Determine the initial direction
    if l[1] > l[0]:
        direction = 'increasing'
    elif l[1] < l[0]:
        direction = 'decreasing'
    else:
        # All elements are equal, so it's both increasing and decreasing
        return True
    # Check each consecutive pair
    for i in range(1, len(l)):
        current = l[i]
        next_val = l[i+1]
        if direction == 'increasing':
            if current > next_val:
                return False
        elif direction == 'decreasing':
            if current < next_val:
                return False
    return True

def common(l1, l2):
