    return sorted(common_elements)

def correct_bracketing(brackets: str) -> bool:
    stack = []
    for char in brackets:
        if char == '(':
            stack.append(char)
        else:
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

def fibfib(n):
    if n == 0:
        return 0
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    a, b, c = 0, 0, 1
    for i in range(3, n + 1):
        next_val = a + b + c
        a, b, c = b, c, next_val
    return c

def digitSum(s):
    total = 0
    for char in s:
        if char.isupper():
            total += ord(char)
    return total

def pluck(arr):
    min_even = None
    min_index = -1
    for i, v in enumerate(arr):
        if v % 2 == 0:
            if min_even is None:
                min_even = v
                min_index = i
            else:
                if v < min_even:
                    min_even = v
                    min_index = i
                elif v == min_even:
                    if i < min_index:
                        min_index = i
    return [min_even, min_index] if min_even is not None else []

from collections import Counter

def search(lst):
    counts = Counter(lst)
    unique = sorted(counts.keys(), reverse=True)
    for num in unique:
        if counts[num] >= num:
            return num
    return -1

