def triangle_area(a, b, c):
    if (a + b <= c) or (a + c <= b) or (b + c <= a):
        return -1
    s = (a + b + c) / 2
    area = (s * (s - a) * (s - b) * (s - c)) ** 0.5
    return round(area, 2)

def will_it_fly(q, w):
    if not isinstance(q, list):
        return False
    if q == q[::-1]:
        total = sum(q)
        return total <= w
    else:
        return False

