def hex_key(num):
    primes = {'2', '3', '5', '7', 'B', 'D'}
    count = 0
    for c in num:
        if c in primes:
            count += 1
    return count

def decimal_to_binary(decimal):
    binary_str = bin(decimal)[2:]
    return 'db' + binary_str + 'db'

def is_happy(s):
    if len(s) < 3:
        return False
    for i in range(len(s) - 2):
        triplet = s[i:i+3]
        if len(set(triplet)) != 3:
            return False
    return True

def prime_length(string):
    length = len(string)
    if length < 2:
        return False
    for i in range(2, int(length**0.5) + 1):
        if length % i == 0:
            return False
    return True

def starts_one_ends(n):
    if n == 1:
        return 1
    else:
        return 18 * (10 ** (n - 2))

def add(lst):
    total = 0
    for index, num in enumerate(lst):
        if index % 2 == 1 and num % 2 == 0:
            total += num
    return total

def get_row(lst, x):
    result = []
    for row_idx, row in enumerate(lst):
        for col_idx, value in enumerate(row):
            if value == x:
                result.append((row_idx, col_idx))
    sorted_result = sorted(result, key=lambda t: (t[0], -t[1]))
    return sorted_result

def sort_array(array):
    if not array:
        return []
    first = array[0]
    last = array[-1]
    if (first + last) % 2 == 1:
        sorted_arr = sorted(array)
    else:
        sorted_arr = sorted(array, reverse=True)
    return sorted_arr

def next_smallest(lst):
    if len(lst) < 2:
        return None
    sorted_lst = sorted(lst)
    unique_sorted = []
    prev = None
    for num in sorted_lst:
        if num != prev:
            unique_sorted.append(num)
            prev = num
    if len(unique_sorted) < 2:
        return None
    return unique_sorted[1]

def encode(message):
    result = []
    for char in message:
        if char.isalpha():
            new_char = char.lower() if char.isupper() else char.upper()
            if new_char in {'a', 'e', 'i', 'o', 'u'}:
                pos = ord(new_char) - ord('a')
                new_pos = (pos + 2) % 26
                new_char = chr(new_pos + ord('a'))
            result.append(new_char)
        else:
            result.append(char)
    return ''.join(result)

def skjkasdkd(lst):
    def is_prime(n):
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    largest_prime = None
    for num in lst:
        if is_prime(num):
            if largest_prime is None or num > largest_prime:
                largest_prime = num

    if largest_prime is not None:
        s = 0
        num = largest_prime
        while num > 0:
            s += num % 10
            num = num // 10
        return s
    else:
        return 0

