    for key in dict:
        if not isinstance(key, str):
            return False
        if not (key.islower() or key.isupper()):
            return False
    return True

def count_up_to(n):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    if n <= 1:
        return []

    primes = []
    for num in range(2, n):
        if is_prime(num):
            primes.append(num)

    return primes[:n]

