    count = 0
    vowels = {'A', 'E', 'I', 'O', 'U'}
    for index, char in enumerate(s):
        if char.isupper() and char in vowels:
            count += 1
    return count

def remove_first_last(s, c):
    if not s:
        return ""
    first = s.find(c)
    last = s.rfind(c)
    if first == last:
        return ""
    return s[1:-1]

def is_woodball(num):
    s = str(num)
    if len(s) < 10:
        return False
    return set(s) >= set('0123456789')

def largest_number(digits):
    s = ''.join(str(d) for d in digits)
    if len(s) == 0:
        return 0
    if s[0] == '0':
        for i in range(1, len(s)):
            if s[i] != '0':
                s, s[i] = s[i], s[0]
                break
    return int(s)

def count_substrings(s):
    count = 0
    n = len(s)
    for i in range(n):
        for j in range(i, n):
            substr = s[i:j+1]
            total = sum(int(c) for c in substr)
            if total == (j - i + 1):
                count += 1
    return count

