    return min(numbers)

def max_difference(lst):
    if len(lst) < 2:
        return 0
    max_diff = float('-inf')
    for i in range(len(lst) - 1):
        current = lst[i]
        previous = lst[i + 1]
        diff = current - previous
        if diff > max_diff:
            max_diff = diff
    return max_diff

def flatten_and_sum(lst):
    def flatten(lst):
        result = []
        for element in lst:
            if isinstance(element, list):
                result.extend(flatten(element))
            else:
                result.append(element)
        return result

    flattened = flatten(lst)
    return sum(flattened)

def is_monotonic(arr):
    if len(arr) <= 1:
        return True
    trend = 0
    for i in range(1, len(arr)):
        current = arr[i]
        prev = arr[i-1]
        if current > prev:
            new_trend = 1
        elif current < prev:
            new_trend = -1
        else:
            new_trend = 0
        # Check if new_trend is different from previous trend
        if new_trend != 0 and new_trend != 1 and new_trend != -1:
            return False
        trend = new_trend
    return True

def all_tuples_equal(*tuples):
    # Check if all arguments are tuples
    if not all(isinstance(arg, tuple) for arg in tuples):
        return False
    # If no tuples, return True
    if len(tuples) == 0:
        return True
    # Get the lengths of each tuple
    lengths = [len(t) for t in tuples]
    # Check if all lengths are equal
    return all(l == lengths[0] for l in lengths)

def is_diff_of_squares(n):
    if n < 0:
        return False
    if n == 0:
        return True
    return n % 2 == 1 or n % 4 == 0

def find_divisible_tuples(tuples, k):
    result = []
    for tup in tuples:
        all_divisible = True
        for num in tup:
            if num % k != 0:
                all_divisible = False
                break
        if all_divisible:
            result.append(tup)
    return result

