def merge_three(d1, d2, d3):
    all_keys = set(d1.keys()).union(set(d2.keys())).union(set(d3.keys()))
    merged = {}
    for key in all_keys:
        merged[key] = d1.get(key, 0) + d2.get(key, 0) + d3.get(key, 0)
    return merged

