    return counts

def longest_word_length(s):
    if s is None or s.strip() == '':
        return 0
    words = s.split()
    max_length = 0
    for word in words:
        current_length = len(word)
        if current_length > max_length:
            max_length = current_length
    return max_length

def is_undulating(n):
    s = str(n)
    if len(s) < 2:
        return False
    if s[0] == '0':
        return False
    prev = s[0]
    current = s[1]
    for i in range(2, len(s)):
        if i % 2 == 0:
            if s[i] != prev:
                return False
        else:
            if s[i] != current:
                return False
        prev = s[i]
    return True

def find_first_value(tuples):
    min_second = min(t[1] for t in tuples)
    for t in tuples:
        if t[1] == min_second:
            return t[0]

def smallest_list_length(list_of_lists):
    min_length = float('inf')
    for sublist in list_of_lists:
        current_length = len(sublist)
        if current_length < min_length:
            min_length = current_length
    return min_length

def number_of_divisors(n):
    if n == 0:
        return 0
    if n == 1:
        return 1
    count = 1
    i = 2
    while i * i <= n:
        exponent = 0
        while n % i == 0:
            exponent += 1
            n = n // i
        if exponent > 0:
            count *= (exponent + 1)
        i += 1
    if n > 1:
        count *= 2
    return count

from collections import Counter

def frequency(lst):
