def decimal_to_binary(n):
    if n == 0:
        return '0'
    binary = []
    while n > 0:
        remainder = n % 2
        binary.append(str(remainder))
        n = n // 2
    return ''.join(reversed(binary))

def snake_to_camel(s):
    words = s.split('_')
    camel = []
    for word in words:
        if word:
            camel.append(word[0].upper() + word[1:].lower() if word else '')
    return ''.join(camel)

def append_tuples(tuples_list, elements_list):
    result = []
    for t in tuples_list:
