            new_t += (e,)
            result.append(new_t)
    return result

def find_common_elements(nested_lists):
    if not nested_lists:
        return []
    current = set(nested_lists[0])
    for sublist in nested_lists[1:]:
        current = current.intersection(sublist)
        if not current:
            break
    return sorted(current)

