import math

def sum_common_divisors(a, b):
    g = math.gcd(abs(a), abs(b))
    def get_divisors(n):
        divisors = set()
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                divisors.add(i)
                divisors.add(n // i)
        return divisors
    divisors = get_divisors(g)
    return sum(divisors)

def is_magic_square(matrix):
    n = len(matrix)
    if n == 0:
        return False
    if n != len(matrix[0]):
        return False

    magic = sum(matrix[0])

    # Check all rows
    for row in matrix:
        if sum(row) != magic:
            return False

    # Check all columns
    for i in range(n):
        column_sum = sum(matrix[j][i] for j in range(n))
        if column_sum != magic:
            return False

    # Check main diagonal
    main_diag_sum = sum(matrix[i][i] for i in range(n))
    if main_diag_sum != magic:
        return False

    # Check anti-diagonal
    anti_diag_sum = sum(matrix[i][n-1-i] for i in range(n))
    if anti_diag_sum != magic:
        return False

    return True

