def ratio_of_zero_to_nonzero(arr):
    zero_count = 0
    non_zero_count = 0
    for num in arr:
        if num == 0:
            zero_count += 1
        else:
            non_zero_count += 1
    if non_zero_count == 0:
        return 0
    else:
        return zero_count / non_zero_count

